window.__snap = () => {
  const seen = (element) => element.getClientRects().length > 0;
  const items = [...document.querySelectorAll('#todos > li')].filter(seen);
  const first = (li, selector) => li.querySelector(selector);
  const position = (li, selector) => [...li.querySelectorAll('*')].indexOf(first(li, selector));
  return {
    titles: items.map((li) => first(li, '.title') ? first(li, '.title').textContent.trim() : null),
    spans: items.map((li) => Boolean(first(li, 'span.title'))),
    done: items.map((li) => li.classList.contains('done')),
    checked: items.map((li) => first(li, 'input[type=checkbox]') ? first(li, 'input[type=checkbox]').checked : null),
    labels: items.map((li) => first(li, 'button.delete') ? first(li, 'button.delete').getAttribute('aria-label') : null),
    ordered: items.map((li) => { const order = ['input[type=checkbox]', '.title', 'button.delete'].map((s) => position(li, s)); return order.every((n) => n >= 0) && order[0] < order[1] && order[1] < order[2]; }),
    count: document.getElementById('count') ? document.getElementById('count').textContent.trim() : null,
    pressed: ['all', 'active', 'done'].map((name) => { const b = document.querySelector('[data-filter="' + name + '"]'); return b ? b.getAttribute('aria-pressed') : null; }),
    clearDisabled: document.getElementById('clear-done') ? document.getElementById('clear-done').disabled : null,
    input: document.querySelector('#new-todo input') ? document.querySelector('#new-todo input').value : null,
    inputFocused: document.activeElement === document.querySelector('#new-todo input'),
    editing: (() => { const box = [...document.querySelectorAll('#todos input.edit')].find(seen); return box ? box.value : null; })(),
    editFocused: Boolean(document.activeElement && document.activeElement.classList.contains('edit')),
    markup: document.querySelectorAll('#todos b').length,
  };
}, true

